DO $exp$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Farmacología del Sistema Nervioso Central$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Farmacología del Sistema Nervioso Central$t$;
    RETURN;
  END IF;

  -- 01. Caso clínico: mujer en edad fértil con valproato y carbamazepina
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Dos riesgos en una fórmula","texto":"Una mujer joven con epilepsia recibe valproato y carbamazepina. El valproato es teratogénico y la carbamazepina induce el metabolismo de los anticonceptivos. El caso exige coordinación, consejería y un plan reproductivo."},"objetivos":["Evaluar el riesgo teratogénico.","Revisar la interacción con anticonceptivos.","Proponer alternativas.","Documentar el plan."],"conceptos":[{"icono":"AlertTriangle","termino":"Valproato","definicion":"Teratogénico y neurotóxico."},{"icono":"Network","termino":"Inducción","definicion":"Carbamazepina reduce anticonceptivos."},{"icono":"Users","termino":"Consejo","definicion":"Planificación y anticoncepción."},{"icono":"ShieldCheck","termino":"Alternativa","definicion":"Lamotrigina o levetiracetam."}],"secciones":[{"titulo":"Evaluación","parrafos":["La paciente tiene epilepsia y recibe valproato y carbamazepina. El valproato aumenta el riesgo de malformaciones y problemas del neurodesarrollo, especialmente con dosis altas y exposición en el primer trimestre. La carbamazepina induce enzimas y puede reducir la eficacia de los anticonceptivos hormonales.","Se revisan el tipo de crisis, la respuesta, la dosis, el deseo de embarazo y la anticoncepción. El objetivo es controlar las crisis con el menor riesgo reproductivo."]},{"titulo":"Intervención","parrafos":["Se coordina con neurología para valorar el cambio a lamotrigina o levetiracetam, con titulación lenta y control de crisis. Se recomienda ácido fólico si hay posibilidad de embarazo, anticoncepción eficaz y un método adicional si se mantiene un inductor enzimático.","La educación incluye la importancia de planificar el embarazo, no suspender el antiepiléptico sin supervisión y reportar rash o cambios de conducta. El QF documenta la consejería y las alternativas discutidas."]},{"titulo":"Seguimiento","parrafos":["Se controlan las crisis, los efectos adversos y la adherencia. Si se cambia de fármaco, se monitorizan los niveles y la respuesta. La comunicación entre neurología, ginecología y farmacia es clave.","El caso muestra que la seguridad reproductiva es parte de la farmacoterapia y que el QF puede liderar la revisión y la educación."]}],"errores":[{"error":"No advertir el riesgo del valproato.","correccion":"Puede causar daño fetal."},{"error":"Ignorar la inducción enzimática.","correccion":"Fallo anticonceptivo."},{"error":"Cambiar sin control de crisis.","correccion":"Riesgo de descompensación."}],"comprueba":[{"pregunta":"¿Qué riesgo tiene el valproato?","respuesta":"Malformaciones y neurodesarrollo."},{"pregunta":"¿Qué hace la carbamazepina?","respuesta":"Induce enzimas y reduce anticonceptivos."},{"pregunta":"¿Qué alternativa se valora?","respuesta":"Lamotrigina o levetiracetam."}],"resumen":["La seguridad reproductiva es prioritaria.","El valproato es teratogénico.","La carbamazepina induce enzimas.","El cambio se coordina y se documenta."],"referencias":[{"cita":"Agencia Europea de Medicamentos. Medidas para prevenir la exposición al valproato durante el embarazo. EMA; 2018.","url":"https://www.ema.europa.eu/"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Evaluación de riesgo y plan reproductivo.","alt":"Caso de mujer fértil con antiepilépticos"}],"keywords":["valproato embarazo","carbamazepina anticonceptivo","epilepsia mujer fértil"],"mapa":{"centro":"Mujer fértil","ramas":[{"titulo":"Riesgo","icono":"AlertTriangle","nodos":["Valproato","Dosis","Trimestre"]},{"titulo":"Interacción","icono":"Network","nodos":["Anticonceptivo","Inducción"]},{"titulo":"Alternativa","icono":"ShieldCheck","nodos":["Lamotrigina","Levetiracetam"]},{"titulo":"Plan","icono":"FileCheck","nodos":["Ácido fólico","Registro","Seguimiento"]}]},"proceso":{"titulo":"Plan reproductivo","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Crisis y deseo de embarazo.","icono":"ClipboardList","evidencia":"Entrevista."},{"titulo":"Riesgo","detalle":"Valproato y anticoncepción.","icono":"AlertTriangle","evidencia":"Evaluación."},{"titulo":"Alternativa","detalle":"Cambio coordinado.","icono":"ShieldCheck","evidencia":"Plan."},{"titulo":"Educar","detalle":"Ácido fólico y plan.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguir","detalle":"Crisis y tolerancia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Valproato y anticonceptivo","contexto":"Mujer de 24 años con valproato y carbamazepina que planea embarazo.","pregunta":"¿Qué prioriza el QF?","opciones":[{"texto":"Mantener el esquema sin cambios.","correcta":false,"retro":"Hay riesgos importantes."},{"texto":"Coordinar alternativa y consejo reproductivo.","correcta":true,"retro":"Reduce el riesgo."},{"texto":"Suspender todo de golpe.","correcta":false,"retro":"Riesgo de crisis."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Caso clínico: mujer en edad fértil con valproato y carbamazepina$t$ AND deleted_at IS NULL
