     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 02. Introducción a la unidad: neurodegeneración y abordaje farmacológico
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Cuando las neuronas se pierden","texto":"En el Parkinson se pierden neuronas dopaminérgicas; en el Alzheimer, neuronas colinérgicas y glutamatérgicas. El tratamiento actual es sintomático en gran medida. Entender la neurodegeneración permite usar los fármacos con expectativas realistas."},"objetivos":["Reconocer los mecanismos de neurodegeneración.","Diferenciar el tratamiento sintomático del modificador.","Conectar las dianas con los fármacos.","Aplicar expectativas realistas."],"conceptos":[{"icono":"Database","termino":"Agregación","definicion":"Proteínas mal plegadas."},{"icono":"Activity","termino":"Dopamina","definicion":"Déficit en la sustancia negra."},{"icono":"Network","termino":"Acetilcolina","definicion":"Déficit en el Alzheimer."},{"icono":"ShieldCheck","termino":"Sintomático","definicion":"Mejora síntomas sin frenar la enfermedad."}],"secciones":[{"titulo":"Mecanismos","parrafos":["La neurodegeneración implica agregación de proteínas, estrés oxidativo, disfunción mitocondrial, neuroinflamación y muerte neuronal. En el Parkinson se afectan las neuronas dopaminérgicas de la sustancia negra; en el Alzheimer, las vías colinérgicas y glutamatérgicas, con placas de amiloide y ovillos de tau.","Los fármacos actuales mejoran los síntomas, pero en la mayoría de los casos no detienen la enfermedad. Los anticuerpos anti-amiloide buscan modificar el curso en fases tempranas, con beneficios modestos y riesgos."]},{"titulo":"Dianas","parrafos":["En el Parkinson se reemplaza la dopamina o se estimulan sus receptores. En el Alzheimer se aumentan la acetilcolina o se modula el glutamato. Los fármacos deben atravesar la barrera hematoencefálica y tener un perfil de seguridad adecuado para el uso crónico.","La elección depende de la fase, los síntomas, la edad y las comorbilidades. La educación y el apoyo al cuidador son parte del tratamiento."]},{"titulo":"Expectativas","parrafos":["El paciente y la familia deben comprender qué se puede esperar: mejoría sintomática, enlentecimiento de algunos síntomas y manejo de las complicaciones. La rehabilitación, el ejercicio y el apoyo multidisciplinario son fundamentales.","El QF revisa la adherencia, las interacciones y los efectos adversos. También detecta la carga anticolinérgica y los fármacos que empeoran los síntomas."]}],"errores":[{"error":"Prometer curación.","correccion":"El tratamiento es sintomático."},{"error":"Ignorar al cuidador.","correccion":"Es parte del plan."},{"error":"No revisar la carga anticolinérgica.","correccion":"Empeora la cognición."}],"comprueba":[{"pregunta":"¿Qué se pierde en el Parkinson?","respuesta":"Neuronas dopaminérgicas."},{"pregunta":"¿Qué se modula en el Alzheimer?","respuesta":"Acetilcolina y glutamato."},{"pregunta":"¿Qué busca el tratamiento?","respuesta":"Mejorar síntomas y función."}],"resumen":["La neurodegeneración es multifactorial.","El tratamiento es principalmente sintomático.","Las dianas guían la elección.","El apoyo multidisciplinario es clave."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Unidad 4","descripcion":"Mecanismos de neurodegeneración y dianas.","alt":"Neurodegeneración y farmacología"}],"keywords":["neurodegeneración","parkinson","alzheimer","levodopa"],"mapa":{"centro":"Neurodegeneración","ramas":[{"titulo":"Parkinson","icono":"Activity","nodos":["Dopamina","Levodopa","Agonistas"]},{"titulo":"Alzheimer","icono":"Network","nodos":["Acetilcolina","Memantina","Amiloide"]},{"titulo":"Mecanismos","icono":"Database","nodos":["Estrés oxidativo","Inflamación","Muerte"]},{"titulo":"Metas","icono":"Target","nodos":["Función","Síntomas","Calidad"]}]},"proceso":{"titulo":"Abordar la neurodegeneración","intro":"","pasos":[{"titulo":"Diagnóstico","detalle":"Enfermedad y fase.","icono":"Search","evidencia":"Clínica."},{"titulo":"Síntomas","detalle":"Motores o cognitivos.","icono":"ClipboardList","evidencia":"Evaluación."},{"titulo":"Fármaco","detalle":"Diana y perfil.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Revisar","detalle":"Efectos y carga.","icono":"Eye","evidencia":"Seguimiento."},{"titulo":"Apoyar","detalle":"Cuidador y rehabilitación.","icono":"Users","evidencia":"Plan."}]},"caso":{"titulo":"Dopamina y barrera","contexto":"Paciente con Parkinson que pregunta por qué no se usa dopamina oral.","pregunta":"¿Cuál es la razón?","opciones":[{"texto":"No atraviesa la barrera hematoencefálica.","correcta":true,"retro":"Se usa levodopa."},{"texto":"Es demasiado económica.","correcta":false,"retro":"No es el motivo."},{"texto":"No existe.","correcta":false,"retro":"Existe, pero no cruza."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: neurodegeneración y abordaje farmacológico$t$ AND deleted_at IS NULL
