  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 03. Levodopa/carbidopa: mecanismo, farmacocinética y complicaciones motoras
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La levodopa que llega al cerebro","texto":"La levodopa atraviesa la barrera y se convierte en dopamina. La carbidopa evita su degradación periférica. Con el tiempo aparecen fluctuaciones y discinesias. Conocer la farmacocinética permite ajustar el tratamiento."},"objetivos":["Explicar el mecanismo.","Aplicar la dosis y la titulación.","Reconocer las complicaciones motoras.","Educar y monitorizar."],"conceptos":[{"icono":"Activity","termino":"Levodopa","definicion":"Precursor de la dopamina."},{"icono":"ShieldCheck","termino":"Carbidopa","definicion":"Inhibe la descarboxilasa periférica."},{"icono":"Timer","termino":"Wearing-off","definicion":"Fin de dosis precoz."},{"icono":"Repeat","termino":"Discinesia","definicion":"Movimientos involuntarios."}],"secciones":[{"titulo":"Mecanismo y farmacocinética","parrafos":["La levodopa atraviesa la barrera hematoencefálica por el transportador LAT1 y se convierte en dopamina en el cerebro. La carbidopa inhibe la descarboxilasa periférica y reduce la conversión periférica, lo que disminuye las náuseas y aumenta la disponibilidad central.","La absorción depende del vaciamiento gástrico y de la competencia con aminoácidos de la dieta. Las comidas ricas en proteína pueden reducir su efecto. La vida media es corta, lo que explica las fluctuaciones."]},{"titulo":"Complicaciones motoras","parrafos":["Con el tiempo aparecen fluctuaciones: el wearing-off (fin de dosis precoz), el fenómeno on-off y las discinesias. Se manejan ajustando la frecuencia, usando formulaciones de liberación prolongada, añadiendo inhibidores de la COMT o MAO-B, o con dispositivos.","Las discinesias pueden ser molestas y limitar la dosis. La educación sobre el horario y la respuesta es clave. No se debe suspender bruscamente por el riesgo de un síndrome similar al neuroléptico maligno."]},{"titulo":"Seguridad","parrafos":["Los efectos adversos incluyen náuseas, hipotensión ortostática, somnolencia, confusión, alucinaciones y movimientos involuntarios. Se usa con precaución en glaucoma de ángulo cerrado, arritmias y úlcera péptica. La interacción con IMAO no selectivos es peligrosa.","El QF revisa la adherencia, el horario y las interacciones. La educación incluye no suspender de golpe y reportar cambios de movimiento o conducta."]}],"errores":[{"error":"Suspender bruscamente.","correccion":"Riesgo de síndrome similar al NMS."},{"error":"No revisar la proteína de la dieta.","correccion":"Reduce la absorción."},{"error":"Ignorar las fluctuaciones.","correccion":"Afectan la función."}],"comprueba":[{"pregunta":"¿Qué hace la carbidopa?","respuesta":"Inhibe la descarboxilasa periférica."},{"pregunta":"¿Qué es el wearing-off?","respuesta":"Fin de dosis precoz."},{"pregunta":"¿Qué se evita al suspender?","respuesta":"Un síndrome similar al NMS."}],"resumen":["La levodopa es eficaz y atraviesa la barrera.","La carbidopa reduce los efectos periféricos.","Las fluctuaciones son frecuentes.","El ajuste y la educación mejoran la función."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Parkinson","descripcion":"Levodopa, carbidopa y fluctuaciones.","alt":"Levodopa/carbidopa en Parkinson"}],"keywords":["levodopa","carbidopa","wearing-off","discinesia"],"mapa":{"centro":"Levodopa","ramas":[{"titulo":"Mecanismo","icono":"Activity","nodos":["LAT1","Dopamina","Sustancia negra"]},{"titulo":"Dosis","icono":"Pill","nodos":["Inicio","Titulación","Formas"]},{"titulo":"Complicaciones","icono":"Timer","nodos":["Wearing-off","On-off","Discinesia"]},{"titulo":"Educación","icono":"Users","nodos":["Comidas","Adherencia","Alarma"]}]},"proceso":{"titulo":"Optimizar levodopa","intro":"","pasos":[{"titulo":"Inicio","detalle":"Dosis baja y titulación.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Horario","detalle":"Comidas y tomas.","icono":"Timer","evidencia":"Registro."},{"titulo":"Fluctuación","detalle":"Wearing-off.","icono":"LineChart","evidencia":"Diario."},{"titulo":"Ajuste","detalle":"Frecuencia o adyuvante.","icono":"Settings","evidencia":"Plan."},{"titulo":"Educar","detalle":"No suspender.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Fin de dosis","contexto":"Paciente con Parkinson que presenta temblor y rigidez antes de la siguiente dosis.","pregunta":"¿Qué fenómeno es?","opciones":[{"texto":"Wearing-off.","correcta":true,"retro":"Fin de dosis precoz."},{"texto":"Discinesia.","correcta":false,"retro":"Son movimientos involuntarios."},{"texto":"Síndrome neuroléptico.","correcta":false,"retro":"El contexto es otro."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Levodopa/carbidopa: mecanismo, farmacocinética y complicaciones motoras$t$ AND deleted_at IS NULL
