  -- 04. Agonistas dopaminérgicos, IMAO-B, ICOMT y amantadina
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Las opciones alrededor de la levodopa","texto":"Los agonistas dopaminérgicos, los IMAO-B, los ICOMT y la amantadina amplían el manejo del Parkinson. Cada uno tiene un perfil distinto y efectos adversos que el paciente debe conocer."},"objetivos":["Diferenciar los adyuvantes.","Aplicar sus indicaciones.","Reconocer los efectos adversos.","Elegir según el paciente."],"conceptos":[{"icono":"Activity","termino":"Agonista","definicion":"Estimula receptores dopaminérgicos."},{"icono":"Timer","termino":"IMAO-B","definicion":"Reduce el catabolismo de la dopamina."},{"icono":"Repeat","termino":"ICOMT","definicion":"Prolonga la levodopa."},{"icono":"AlertTriangle","termino":"Impulsos","definicion":"Riesgo con agonistas."}],"secciones":[{"titulo":"Agonistas dopaminérgicos","parrafos":["El pramipexol, el ropinirol y la rotigotina estimulan directamente los receptores dopaminérgicos. Se usan en fases tempranas para retrasar la levodopa o como adyuvantes. Tienen una vida media más larga y menos fluctuaciones, pero más efectos neuropsiquiátricos.","Pueden causar somnolencia, alucinaciones, hipotensión y trastornos del control de impulsos, como juego patológico o hipersexualidad. La educación y la vigilancia son esenciales."]},{"titulo":"IMAO-B e ICOMT","parrafos":["La selegilina y la rasagilina inhiben la MAO-B y reducen la degradación de la dopamina. Son útiles en fases tempranas y como adyuvantes. La rasagilina tiene menos metabolitos anfetamínicos. Se evitan con otros inhibidores de la MAO.","La entacapona y la tolcapona inhiben la COMT y prolongan el efecto de la levodopa. La entacapona se usa con cada dosis y puede causar diarrea y coloración de la orina. La tolcapona requiere control hepático. La amantadina se usa para las discinesias y tiene efectos antivirales."]},{"titulo":"Elección","parrafos":["La elección depende de la fase, los síntomas, la edad, la cognición y el riesgo de efectos adversos. Los agonistas son útiles en pacientes jóvenes sin deterioro cognitivo; los ICOMT en fluctuaciones. La revisión de la medicación y la educación son parte del plan.","El QF documenta la tolerancia y los cambios de conducta. La comunicación con neurología permite ajustar sin perder el control. La revisión debe incluir la función renal y hepática, y la educación sobre la somnolencia y los impulsos."]}],"errores":[{"error":"No preguntar por impulsos.","correccion":"Los agonistas los causan."},{"error":"Combinar IMAO sin control.","correccion":"Riesgo serotoninérgico."},{"error":"No controlar el hígado con tolcapona.","correccion":"Hepatotoxicidad."}],"comprueba":[{"pregunta":"¿Qué efecto tienen los agonistas?","respuesta":"Estimulan receptores dopaminérgicos."},{"pregunta":"¿Qué hace la entacapona?","respuesta":"Inhibe la COMT."},{"pregunta":"¿Qué efecto adverso es típico?","respuesta":"Trastornos del control de impulsos."}],"resumen":["Los adyuvantes amplían el manejo.","Los agonistas causan efectos neuropsiquiátricos.","Los ICOMT prolongan la levodopa.","La vigilancia y la educación son clave."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Adyuvantes","descripcion":"Opciones farmacológicas en Parkinson.","alt":"Agonistas, IMAO-B, ICOMT y amantadina"}],"keywords":["pramipexol","rasagilina","entacapona","amantadina"],"mapa":{"centro":"Adyuvantes","ramas":[{"titulo":"Agonistas","icono":"Activity","nodos":["Pramipexol","Ropinirol","Rotigotina"]},{"titulo":"IMAO-B","icono":"Timer","nodos":["Selegilina","Rasagilina"]},{"titulo":"ICOMT","icono":"Repeat","nodos":["Entacapona","Tolcapona"]},{"titulo":"Amantadina","icono":"Pill","nodos":["Discinesia","Antiviral"]}]},"proceso":{"titulo":"Elegir adyuvante","intro":"","pasos":[{"titulo":"Fase","detalle":"Temprana o avanzada.","icono":"LineChart","evidencia":"Clínica."},{"titulo":"Síntoma","detalle":"Fluctuación o discinesia.","icono":"Activity","evidencia":"Evaluación."},{"titulo":"Riesgo","detalle":"Conducta y cognición.","icono":"AlertTriangle","evidencia":"Historia."},{"titulo":"Elegir","detalle":"Agonista, IMAO o ICOMT.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Seguir","detalle":"Efecto y tolerancia.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Juego patológico","contexto":"Paciente con pramipexol que desarrolla juego patológico.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Ignorar el cambio de conducta.","correcta":false,"retro":"Es un efecto del agonista."},{"texto":"Alertar y coordinar el ajuste.","correcta":true,"retro":"Requiere manejo."},{"texto":"Aumentar la dosis.","correcta":false,"retro":"Empeora."}]}}$j$::jsonb;
