  -- 05. Caso clínico: Parkinson avanzado con fluctuaciones y trastorno del control de impulsos
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El impulso que nadie preguntó","texto":"Un paciente con Parkinson avanzado tiene fluctuaciones motoras y, además, apuestas compulsivas. El trastorno del control de impulsos es un efecto de los agonistas dopaminérgicos. Detectarlo cambia el plan."},"objetivos":["Analizar las fluctuaciones.","Reconocer el trastorno del control de impulsos.","Ajustar el tratamiento.","Coordinar el apoyo familiar."],"conceptos":[{"icono":"Timer","termino":"Fluctuación","definicion":"Variación del efecto motor."},{"icono":"AlertTriangle","termino":"Impulsos","definicion":"Juego, compras o hipersexualidad."},{"icono":"Activity","termino":"Discinesia","definicion":"Movimientos involuntarios."},{"icono":"Users","termino":"Familia","definicion":"Apoyo y detección."}],"secciones":[{"titulo":"Evaluación","parrafos":["El paciente tiene fluctuaciones motoras y discinesias. Además, presenta apuestas compulsivas y compras impulsivas. Los agonistas dopaminérgicos son una causa frecuente de trastorno del control de impulsos. Se revisa la dosis, el inicio y el impacto familiar.","Se evalúan la fase de la enfermedad, la respuesta a la levodopa, las comorbilidades y el riesgo neuropsiquiátrico. La entrevista debe preguntar de forma directa por estos síntomas."]},{"titulo":"Intervención","parrafos":["Se reduce o suspende el agonista de forma coordinada y se ajusta la levodopa u otro adyuvante. Se puede añadir un ICOMT o un IMAO-B según las fluctuaciones. El manejo del trastorno del control de impulsos requiere apoyo psicológico y familiar.","La educación incluye reconocer los síntomas, no ocultarlos y consultar. El QF documenta la intervención y coordina con neurología y psiquiatría."]},{"titulo":"Seguimiento","parrafos":["Se controlan los síntomas motores, las discinesias y la conducta. La familia participa en la vigilancia. La reducción del agonista puede empeorar las fluctuaciones, por lo que el ajuste debe ser gradual.","El caso muestra que la farmacología del Parkinson incluye la esfera conductual y que el QF puede detectar efectos que pasan desapercibidos. La entrevista debe hacerse también con la familia, porque el paciente puede minimizar los impulsos. El registro de los síntomas motores y no motores guía el ajuste. La educación sobre la enfermedad y los recursos de apoyo mejora la calidad de vida."]}],"errores":[{"error":"No preguntar por impulsos.","correccion":"Son frecuentes."},{"error":"Suspender bruscamente.","correccion":"Riesgo motor y conductual."},{"error":"No involucrar a la familia.","correccion":"Ayuda a detectar."}],"comprueba":[{"pregunta":"¿Qué fármacos causan impulsos?","respuesta":"Los agonistas dopaminérgicos."},{"pregunta":"¿Cómo se ajusta?","respuesta":"Reduciendo el agonista y ajustando la levodopa."},{"pregunta":"¿Qué se controla?","respuesta":"Motor y conducta."}],"resumen":["Las fluctuaciones requieren ajuste.","Los agonistas causan impulsos.","La reducción es gradual.","La familia y la psicología apoyan."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Fluctuaciones motoras y control de impulsos.","alt":"Parkinson avanzado y control de impulsos"}],"keywords":["parkinson avanzado","fluctuaciones motoras","control de impulsos","pramipexol"],"mapa":{"centro":"Parkinson avanzado","ramas":[{"titulo":"Motor","icono":"Timer","nodos":["Wearing-off","On-off","Discinesia"]},{"titulo":"Conducta","icono":"AlertTriangle","nodos":["Juego","Compras","Sexualidad"]},{"titulo":"Ajuste","icono":"Pill","nodos":["Agonista","Levodopa","Adyuvante"]},{"titulo":"Apoyo","icono":"Users","nodos":["Familia","Psiquiatría","Educación"]}]},"proceso":{"titulo":"Manejar las fluctuaciones","intro":"","pasos":[{"titulo":"Diario","detalle":"Horarios y síntomas.","icono":"ClipboardList","evidencia":"Registro."},{"titulo":"Conducta","detalle":"Preguntar por impulsos.","icono":"AlertTriangle","evidencia":"Entrevista."},{"titulo":"Ajustar","detalle":"Agonista y levodopa.","icono":"Settings","evidencia":"Plan."},{"titulo":"Apoyar","detalle":"Familia y psicología.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguir","detalle":"Motor y conducta.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Apuestas compulsivas","contexto":"Paciente con pramipexol y fluctuaciones que presenta juego patológico.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Aumentar el agonista.","correcta":false,"retro":"Empeora el impulso."},{"texto":"Alertar, reducir y coordinar apoyo.","correcta":true,"retro":"Manejo integral."},{"texto":"Suspender todo de golpe.","correcta":false,"retro":"Riesgo de descompensación."}]}}$j$::jsonb;
