  -- 06. Inhibidores de la colinesterasa y memantina
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La memoria que se apoya en la acetilcolina","texto":"Los inhibidores de la colinesterasa aumentan la acetilcolina y mejoran algunos síntomas del Alzheimer. La memantina modula el glutamato. Ninguno cura, pero pueden mejorar la función y la conducta."},"objetivos":["Explicar el mecanismo.","Aplicar la dosis y la titulación.","Reconocer los efectos adversos.","Revisar la carga anticolinérgica."],"conceptos":[{"icono":"Network","termino":"Acetilcolina","definicion":"Neurotransmisor de la memoria."},{"icono":"ShieldCheck","termino":"Donepezilo","definicion":"Inhibidor de la colinesterasa."},{"icono":"Activity","termino":"Memantina","definicion":"Antagonista del NMDA."},{"icono":"AlertTriangle","termino":"Bradicardia","definicion":"Efecto de los colinesterásicos."}],"secciones":[{"titulo":"Inhibidores de la colinesterasa","parrafos":["El donepezilo, la rivastigmina y la galantamina inhiben la acetilcolinesterasa y aumentan la acetilcolina en la sinapsis. Se usan en el Alzheimer leve a moderado y pueden mejorar la cognición, la conducta y la función. La titulación es gradual.","Los efectos adversos incluyen náuseas, diarrea, anorexia, calambres, bradicardia y síncope. Se usan con precaución en arritmias, úlcera péptica y asma. La rivastigmina tiene menos interacciones hepáticas."]},{"titulo":"Memantina","parrafos":["La memantina es un antagonista no competitivo del receptor NMDA y modula la transmisión glutamatérgica. Se usa en la enfermedad moderada a grave, sola o con un inhibidor de la colinesterasa. Puede causar mareo, cefalea, estreñimiento y somnolencia.","La titulación es gradual. Se ajusta en la insuficiencia renal grave. La evidencia muestra un beneficio modesto en la función y la conducta."]},{"titulo":"Revisión y educación","parrafos":["El QF revisa la carga anticolinérgica de otros fármacos, porque puede contrarrestar el efecto de los colinesterásicos y empeorar la cognición. También revisa las interacciones y la adherencia.","La educación incluye expectativas realistas, efectos adversos y la importancia del cuidador. La suspensión se individualiza y se supervisa. La revisión de la medicación debe incluir los fármacos de venta libre con efecto anticolinérgico y las interacciones con betabloqueadores y antiarrítmicos."]}],"errores":[{"error":"No revisar la carga anticolinérgica.","correccion":"Contrarresta el efecto."},{"error":"Titular rápido.","correccion":"Aumenta los efectos digestivos."},{"error":"Prometer reversión.","correccion":"El beneficio es modesto."}],"comprueba":[{"pregunta":"¿Qué hacen los colinesterásicos?","respuesta":"Aumentan la acetilcolina."},{"pregunta":"¿Qué modula la memantina?","respuesta":"El receptor NMDA."},{"pregunta":"¿Qué efecto adverso vigilar?","respuesta":"Bradicardia y síncope."}],"resumen":["Los colinesterásicos mejoran síntomas.","La memantina modula el glutamato.","La bradicardia y la carga anticolinérgica importan.","Las expectativas deben ser realistas."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Demencias","descripcion":"Colinesterásicos y memantina.","alt":"Inhibidores de la colinesterasa y memantina"}],"keywords":["donepezilo","memantina","alzheimer","colinesterasa"],"mapa":{"centro":"Alzheimer","ramas":[{"titulo":"Colinesterasa","icono":"ShieldCheck","nodos":["Donepezilo","Rivastigmina","Galantamina"]},{"titulo":"Memantina","icono":"Activity","nodos":["NMDA","Moderada-grave"]},{"titulo":"Efectos","icono":"AlertTriangle","nodos":["Digestivo","Bradicardia","Síncope"]},{"titulo":"Revisión","icono":"Eye","nodos":["Anticolinérgicos","Interacciones"]}]},"proceso":{"titulo":"Iniciar tratamiento","intro":"","pasos":[{"titulo":"Fase","detalle":"Leve, moderada o grave.","icono":"LineChart","evidencia":"Evaluación."},{"titulo":"Fármaco","detalle":"Colinesterásico o memantina.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Titular","detalle":"Gradual.","icono":"Timer","evidencia":"Esquema."},{"titulo":"Revisar","detalle":"Bradicardia y carga.","icono":"AlertTriangle","evidencia":"Seguimiento."},{"titulo":"Educar","detalle":"Expectativas.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Donepezilo y bradicardia","contexto":"Paciente con Alzheimer que inicia donepezilo y presenta mareo y pulso lento.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Ignorar los síntomas.","correcta":false,"retro":"Puede ser bradicardia."},{"texto":"Revisar el pulso y las interacciones.","correcta":true,"retro":"Se ajusta el manejo."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Empeora."}]}}$j$::jsonb;
