  -- 07. Anticuerpos anti-amiloide (lecanemab, donanemab): evidencia, ARIA y estado regulatorio
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El fármaco que elimina amiloide","texto":"El lecanemab y el donanemab eliminan placas de amiloide y enlentecen el deterioro en el Alzheimer temprano. También pueden causar ARIA, un efecto adverso que requiere resonancia magnética. La selección y el seguimiento son estrictos."},"objetivos":["Explicar el mecanismo.","Interpretar la evidencia.","Reconocer la ARIA.","Aplicar los criterios de selección."],"conceptos":[{"icono":"Target","termino":"Amiloide","definicion":"Proteína que forma placas."},{"icono":"AlertTriangle","termino":"ARIA","definicion":"Edema o microhemorragia cerebral."},{"icono":"TestTube","termino":"Biomarcador","definicion":"Confirma el amiloide."},{"icono":"Timer","termino":"Infusión","definicion":"Administración intravenosa periódica."}],"secciones":[{"titulo":"Mecanismo y evidencia","parrafos":["El lecanemab y el donanemab son anticuerpos monoclonales que se unen a las placas de amiloide y favorecen su eliminación. En pacientes con enfermedad de Alzheimer temprana y amiloide confirmado, enlentecen modestamente el deterioro cognitivo y funcional.","El beneficio es pequeño y debe compararse con los riesgos y el costo. No están indicados en la enfermedad avanzada ni en otras demencias sin amiloide confirmado."]},{"titulo":"ARIA","parrafos":["La ARIA es la anomalía de imagen relacionada con el amiloide: edema o microhemorragias cerebrales. Puede ser asintomática o causar cefalea, confusión, náuseas y convulsiones. Requiere resonancias magnéticas periódicas y evaluación urgente si aparecen síntomas.","El riesgo aumenta con el alelo APOE ε4, la anticoagulación y las microhemorragias previas. La selección del paciente y la monitorización son esenciales."]},{"titulo":"Estado regulatorio y acceso","parrafos":["Los anticuerpos anti-amiloide han recibido aprobaciones regulatorias en varios países, con criterios específicos. En Colombia, el acceso es limitado y depende de la disponibilidad, el costo y la regulación. La evidencia debe interpretarse con prudencia.","El QF revisa la información, apoya la educación y participa en la farmacovigilancia. La decisión se comparte con el paciente y la familia. La selección requiere confirmar el diagnóstico y el biomarcador, evaluar el riesgo de ARIA y garantizar el acceso a resonancia magnética y seguimiento. El QF documenta la educación y los efectos adversos."]}],"errores":[{"error":"No confirmar amiloide.","correccion":"El fármaco no está indicado."},{"error":"No hacer RM de control.","correccion":"La ARIA puede pasar inadvertida."},{"error":"Prometer curación.","correccion":"El beneficio es modesto."}],"comprueba":[{"pregunta":"¿Qué es la ARIA?","respuesta":"Edema o microhemorragia cerebral."},{"pregunta":"¿En qué fase se usan?","respuesta":"En el Alzheimer temprano."},{"pregunta":"¿Qué confirma la indicación?","respuesta":"El biomarcador de amiloide."}],"resumen":["Los anti-amiloide enlentecen el deterioro.","La ARIA requiere vigilancia.","La selección es estricta.","El acceso y la evidencia deben contextualizarse."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Anti-amiloide","descripcion":"Mecanismo, ARIA y selección.","alt":"Lecanemab y donanemab"}],"keywords":["lecanemab","donanemab","aria","amiloide"],"mapa":{"centro":"Anti-amiloide","ramas":[{"titulo":"Fármacos","icono":"Syringe","nodos":["Lecanemab","Donanemab"]},{"titulo":"Evidencia","icono":"LineChart","nodos":["Deterioro","Fase temprana"]},{"titulo":"ARIA","icono":"AlertTriangle","nodos":["Edema","Hemorragia","RM"]},{"titulo":"Selección","icono":"ClipboardList","nodos":["Biomarcador","Riesgo","Acceso"]}]},"proceso":{"titulo":"Evaluar candidato","intro":"","pasos":[{"titulo":"Diagnóstico","detalle":"Alzheimer temprano.","icono":"Search","evidencia":"Clínica."},{"titulo":"Biomarcador","detalle":"Amiloide confirmado.","icono":"TestTube","evidencia":"Resultado."},{"titulo":"Riesgo","detalle":"APOE y anticoagulación.","icono":"AlertTriangle","evidencia":"Evaluación."},{"titulo":"Infusión","detalle":"Protocolo y RM.","icono":"Syringe","evidencia":"Esquema."},{"titulo":"Seguir","detalle":"ARIA y cognición.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Cefalea durante el tratamiento","contexto":"Paciente con lecanemab que presenta cefalea y confusión.","pregunta":"¿Qué sospecha el QF?","opciones":[{"texto":"ARIA.","correcta":true,"retro":"Requiere evaluación urgente."},{"texto":"Efecto normal.","correcta":false,"retro":"Puede ser grave."},{"texto":"Falta de adherencia.","correcta":false,"retro":"No corresponde."}]}}$j$::jsonb;
