  -- 08. Caso clínico: Alzheimer con carga anticolinérgica y bradicardia
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Los fármacos que borran la memoria","texto":"Un paciente con Alzheimer empeora su cognición y presenta mareo. La carga anticolinérgica y la bradicardia por donepezilo explican parte del cuadro. Revisar la medicación es una intervención clave."},"objetivos":["Identificar la carga anticolinérgica.","Reconocer la bradicardia.","Aplicar la desprescripción.","Educar al cuidador."],"conceptos":[{"icono":"AlertTriangle","termino":"Anticolinérgico","definicion":"Empeora la cognición."},{"icono":"Activity","termino":"Bradicardia","definicion":"Efecto del donepezilo."},{"icono":"Repeat","termino":"Desprescripción","definicion":"Retirar lo innecesario."},{"icono":"Users","termino":"Cuidador","definicion":"Parte del plan de cuidado."}],"secciones":[{"titulo":"Evaluación","parrafos":["El paciente con Alzheimer presenta deterioro cognitivo y mareo. Se revisa la medicación: anticolinérgicos para la vejiga o el sueño, sedantes, y donepezilo con un betabloqueador. La carga anticolinérgica puede contrarrestar el efecto del colinesterásico y aumentar la confusión.","Se miden el pulso y la presión, y se revisan las caídas. La bradicardia por donepezilo puede causar síncope. La revisión de la lista completa es prioritaria."]},{"titulo":"Intervención","parrafos":["Se propone suspender o cambiar los fármacos anticolinérgicos y sedantes innecesarios, y ajustar el donepezilo o el betabloqueador según la frecuencia. La desprescripción es gradual y supervisada. Se educa al cuidador sobre los signos de alarma.","La comunicación con el equipo y la documentación de los cambios permiten evaluar la respuesta. La revisión periódica evita la acumulación de fármacos."]},{"titulo":"Seguimiento","parrafos":["Se controlan la cognición, la conducta, el pulso y las caídas. La carga anticolinérgica se reevalúa. El cuidador recibe apoyo y educación sobre la enfermedad y los medicamentos.","El caso muestra que la farmacología del Alzheimer incluye la revisión de toda la medicación y el cuidado del cuidador. La conciliación en cada transición y la revisión de la lista completa evitan la acumulación de fármacos. La educación sobre la enfermedad y los signos de alarma reduce las crisis familiares. El QF puede liderar la desprescripción coordinada."]}],"errores":[{"error":"No revisar los anticolinérgicos.","correccion":"Empeoran la cognición."},{"error":"Ignorar el pulso.","correccion":"Riesgo de síncope."},{"error":"Desprescribir de golpe.","correccion":"Puede descompensar."}],"comprueba":[{"pregunta":"¿Qué fármacos empeoran la cognición?","respuesta":"Los anticolinérgicos."},{"pregunta":"¿Qué efecto tiene el donepezilo?","respuesta":"Puede causar bradicardia."},{"pregunta":"¿Cómo se desprescribe?","respuesta":"De forma gradual y supervisada."}],"resumen":["La carga anticolinérgica importa.","La bradicardia puede causar síncope.","La desprescripción es gradual.","El cuidador es parte del plan."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Revisión de carga anticolinérgica y pulso.","alt":"Alzheimer y carga anticolinérgica"}],"keywords":["alzheimer","carga anticolinérgica","donepezilo bradicardia","desprescripción"],"mapa":{"centro":"Alzheimer","ramas":[{"titulo":"Cognición","icono":"AlertTriangle","nodos":["Anticolinérgicos","Sedantes","Alcohol"]},{"titulo":"Corazón","icono":"Activity","nodos":["Bradicardia","Síncope","Caídas"]},{"titulo":"Revisión","icono":"Eye","nodos":["Lista","Interacción","Deprescripción"]},{"titulo":"Cuidador","icono":"Users","nodos":["Educación","Alarma","Apoyo"]}]},"proceso":{"titulo":"Revisar la carga","intro":"","pasos":[{"titulo":"Listar","detalle":"Todos los fármacos.","icono":"ClipboardList","evidencia":"Lista."},{"titulo":"Clasificar","detalle":"Anticolinérgicos y sedantes.","icono":"AlertTriangle","evidencia":"Escala."},{"titulo":"Medir","detalle":"Pulso y presión.","icono":"Activity","evidencia":"Signos."},{"titulo":"Deprescribir","detalle":"Gradual y supervisado.","icono":"Repeat","evidencia":"Plan."},{"titulo":"Educar","detalle":"Cuidador y alarma.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Confusión y mareo","contexto":"Paciente con Alzheimer, donepezilo, oxibutinina y betabloqueador que presenta confusión y mareo.","pregunta":"¿Qué revisa el QF?","opciones":[{"texto":"La carga anticolinérgica y la bradicardia.","correcta":true,"retro":"Ambas explican el cuadro."},{"texto":"Solo la dosis de donepezilo.","correcta":false,"retro":"Falta la revisión completa."},{"texto":"Nada; es la enfermedad.","correcta":false,"retro":"Los fármacos contribuyen."}]}}$j$::jsonb;
