  -- 09. Introducción a la unidad: migraña, esclerosis múltiple y espasticidad
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Tres problemas, tres lógicas","texto":"La migraña es un trastorno episódico con CGRP como diana; la esclerosis múltiple es autoinmune y requiere terapias modificadoras; la espasticidad refleja una alteración del control motor. Cada uno tiene una lógica farmacológica distinta."},"objetivos":["Reconocer la fisiopatología de la migraña.","Comprender la esclerosis múltiple.","Explicar la espasticidad.","Conectar las dianas con los fármacos."],"conceptos":[{"icono":"Network","termino":"CGRP","definicion":"Péptido clave en la migraña."},{"icono":"ShieldCheck","termino":"EM","definicion":"Enfermedad autoinmune desmielinizante."},{"icono":"Activity","termino":"Espasticidad","definicion":"Aumento del tono por lesión central."},{"icono":"Target","termino":"Diana","definicion":"Punto de acción del fármaco."}],"secciones":[{"titulo":"Migraña","parrafos":["La migraña es un trastorno episódico con activación del sistema trigeminovascular y liberación de CGRP. El tratamiento agudo aborta la crisis; el preventivo reduce la frecuencia y la gravedad. Los triptanes, los gepantes y los ditanes actúan sobre esta vía.","El uso excesivo de analgésicos puede causar cefalea por abuso de medicación. La educación y el registro de crisis son parte del manejo."]},{"titulo":"Esclerosis múltiple","parrafos":["La esclerosis múltiple es una enfermedad autoinmune que afecta la mielina del sistema nervioso central. Las terapias modificadoras de la enfermedad reducen los brotes y la progresión. La elección depende del fenotipo, la actividad y el riesgo.","El QF participa en la educación, la adherencia, la gestión de efectos adversos y la coordinación. La farmacovigilancia es clave."]},{"titulo":"Espasticidad","parrafos":["La espasticidad es un aumento del tono muscular por lesión de la vía corticoespinal. Se trata con fisioterapia, baclofeno, tizanidina, benzodiacepinas y otros fármacos. La toxina botulínica se usa en focos específicos.","El objetivo es mejorar la función y reducir el dolor, no eliminar el tono. La revisión de la medicación y la educación del cuidador son parte del plan. La espasticidad puede aumentar el riesgo de caídas y úlceras; la fisioterapia y el manejo de la medicación deben coordinarse. La evaluación de la función es más importante que la reducción del tono por sí sola."]}],"errores":[{"error":"No registrar las crisis.","correccion":"Se pierde el patrón."},{"error":"Ignorar el abuso de analgésicos.","correccion":"Perpetúa la cefalea."},{"error":"No revisar la adherencia en EM.","correccion":"Afecta la eficacia."}],"comprueba":[{"pregunta":"¿Qué péptido es clave en la migraña?","respuesta":"El CGRP."},{"pregunta":"¿Qué buscan las DMT?","respuesta":"Reducir brotes y progresión."},{"pregunta":"¿Qué fármaco se usa en espasticidad?","respuesta":"Baclofeno o tizanidina."}],"resumen":["Cada problema tiene una lógica distinta.","La migraña se trata en agudo y prevención.","La EM requiere terapias modificadoras.","La espasticidad busca función."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Unidad 5","descripcion":"Migraña, EM y espasticidad con sus dianas.","alt":"Migraña, esclerosis múltiple y espasticidad"}],"keywords":["migraña","esclerosis múltiple","espasticidad","cgrp"],"mapa":{"centro":"Neuro clínica","ramas":[{"titulo":"Migraña","icono":"Zap","nodos":["CGRP","Triptanes","Gepantes"]},{"titulo":"EM","icono":"ShieldCheck","nodos":["Autoinmune","DMT","Brotes"]},{"titulo":"Espasticidad","icono":"Activity","nodos":["GABA","Baclofeno","Tizanidina"]},{"titulo":"Objetivos","icono":"Target","nodos":["Síntomas","Función","Calidad"]}]},"proceso":{"titulo":"Abordar el problema","intro":"","pasos":[{"titulo":"Diagnóstico","detalle":"Migraña, EM o espasticidad.","icono":"Search","evidencia":"Clínica."},{"titulo":"Objetivo","detalle":"Agudo, preventivo o función.","icono":"Target","evidencia":"Plan."},{"titulo":"Fármaco","detalle":"Diana y perfil.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Revisar","detalle":"Efectos e interacciones.","icono":"Eye","evidencia":"Seguimiento."},{"titulo":"Educar","detalle":"Adherencia y alarma.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Cefalea por abuso","contexto":"Paciente con migraña que usa analgésicos más de 15 días al mes.","pregunta":"¿Qué riesgo presenta?","opciones":[{"texto":"Cefalea por abuso de medicación.","correcta":true,"retro":"Frecuente en migraña."},{"texto":"Ninguno.","correcta":false,"retro":"Empeora la migraña."},{"texto":"Hipertermia maligna.","correcta":false,"retro":"No es el contexto."}]}}$j$::jsonb;
