  -- 10. Tratamiento agudo de la migraña: AINE, triptanes, gepantes y ditanes
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Abortar la crisis a tiempo","texto":"El tratamiento de la migraña aguda debe iniciarse temprano y con el fármaco adecuado. Los AINE, los triptanes, los gepantes y los ditanes ofrecen opciones según la gravedad y las contraindicaciones. El abuso de analgésicos es un riesgo."},"objetivos":["Aplicar el tratamiento agudo.","Diferenciar triptanes, gepantes y ditanes.","Reconocer contraindicaciones.","Prevenir el abuso."],"conceptos":[{"icono":"Zap","termino":"Triptán","definicion":"Agonista 5-HT1B/1D."},{"icono":"Target","termino":"Gepante","definicion":"Antagonista del CGRP."},{"icono":"Activity","termino":"Ditán","definicion":"Agonista 5-HT1F."},{"icono":"AlertTriangle","termino":"Abuso","definicion":"Cefalea por uso excesivo."}],"secciones":[{"titulo":"Primera línea","parrafos":["Los AINE, como ibuprofeno o naproxeno, son útiles en las crisis leves a moderadas. Se toman al inicio de la crisis, con un antiemético si hay náuseas. El paracetamol puede ser una alternativa. El descanso y la hidratación ayudan.","Los triptanes, como sumatriptán o rizatriptán, son eficaces en la migraña moderada a grave. Están contraindicados en la enfermedad coronaria, el accidente cerebrovascular, la hipertensión no controlada y el embarazo. Se usan con precaución en la migraña con aura compleja."]},{"titulo":"Nuevas opciones","parrafos":["Los gepantes, como rimegepant y ubrogepant, son antagonistas del CGRP y se usan en el tratamiento agudo. Tienen menos contraindicaciones cardiovasculares que los triptanes. Los ditanes, como el lasmiditán, son agonistas 5-HT1F y pueden causar mareo y somnolencia; se advierte sobre la conducción.","La elección depende de la frecuencia, la gravedad, las contraindicaciones y el acceso. El registro de crisis ayuda a evaluar la respuesta."]},{"titulo":"Prevención del abuso","parrafos":["El uso de analgésicos o triptanes más de 10-15 días al mes puede causar cefalea por abuso de medicación. Se educa al paciente sobre el límite y se considera un tratamiento preventivo si las crisis son frecuentes.","El QF revisa el uso, la adherencia y las interacciones. La educación y el seguimiento mejoran el control y reducen el riesgo. El registro de crisis y la revisión del uso de medicamentos permiten identificar el abuso y ajustar el tratamiento preventivo."]}],"errores":[{"error":"Usar triptán en cardiopatía.","correccion":"Contraindicado."},{"error":"No tratar temprano.","correccion":"Menos eficacia."},{"error":"Ignorar el abuso.","correccion":"Cefalea por medicación."}],"comprueba":[{"pregunta":"¿Qué contraindicación tienen los triptanes?","respuesta":"Enfermedad coronaria."},{"pregunta":"¿Qué son los gepantes?","respuesta":"Antagonistas del CGRP."},{"pregunta":"¿Cuándo se considera abuso?","respuesta":"Más de 10-15 días al mes."}],"resumen":["El tratamiento temprano es más eficaz.","Los triptanes tienen contraindicaciones.","Los gepantes amplían las opciones.","El abuso de medicación se previene."],"referencias":[{"cita":"International Headache Society. The International Classification of Headache Disorders. 3.ª ed. Cephalalgia. 2018.","url":"https://ichd-3.org/"}],"imagenes":[{"ubicacion":"Migraña","descripcion":"Opciones para la crisis migrañosa.","alt":"Tratamiento agudo de la migraña"}],"keywords":["migraña aguda","triptanes","gepantes","lasmiditán"],"mapa":{"centro":"Migraña aguda","ramas":[{"titulo":"AINE","icono":"Pill","nodos":["Ibuprofeno","Naproxeno","Temprano"]},{"titulo":"Triptanes","icono":"Zap","nodos":["Sumatriptán","Rizatriptán","Contraindicaciones"]},{"titulo":"Gepantes","icono":"Target","nodos":["Rimegepant","Ubrogepant"]},{"titulo":"Ditán","icono":"Activity","nodos":["Lasmiditán","Conducción"]}]},"proceso":{"titulo":"Tratar la crisis","intro":"","pasos":[{"titulo":"Gravedad","detalle":"Leve, moderada o grave.","icono":"Gauge","evidencia":"Evaluación."},{"titulo":"Elegir","detalle":"AINE, triptán o gepante.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Contraindicación","detalle":"Cardíaca o embarazo.","icono":"AlertTriangle","evidencia":"Historia."},{"titulo":"Registrar","detalle":"Frecuencia y respuesta.","icono":"ClipboardList","evidencia":"Diario."},{"titulo":"Prevenir","detalle":"Abuso y tratamiento.","icono":"ShieldCheck","evidencia":"Plan."}]},"caso":{"titulo":"Triptán y cardiopatía","contexto":"Paciente con migraña y enfermedad coronaria que solicita sumatriptán.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Dispensar sin revisar.","correcta":false,"retro":"Está contraindicado."},{"texto":"Ofrecer una alternativa segura.","correcta":true,"retro":"Gepante o AINE según el caso."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Riesgo cardiovascular."}]}}$j$::jsonb;
